<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Fee Receipt</title><link href="{{ asset('css/sms.css') }}" rel="stylesheet"></head><body class="sms-print-page"><div class="sms-print-sheet"><div class="sms-print-header"><h1>{{ \App\Models\Setting::valueOf('college_name','Student Management System') }}</h1><p>{{ \App\Models\Setting::valueOf('college_address','') }}</p><h2>Fee Receipt</h2></div><div class="sms-receipt-grid"><div><span>Receipt No.</span><strong>SMS-FEE-{{ str_pad($payment->id,6,'0',STR_PAD_LEFT) }}</strong></div><div><span>Date</span><strong>{{ $payment->payment_date->format('d M Y') }}</strong></div><div><span>Student</span><strong>{{ $payment->student->user->name }}</strong></div><div><span>Roll No.</span><strong>{{ $payment->student->roll_no }}</strong></div><div><span>Course</span><strong>{{ $payment->student->course->name }}</strong></div><div><span>Session</span><strong>{{ $payment->student->academicSession->name }}</strong></div><div><span>Fee</span><strong>{{ $payment->feeStructure?->name ?? 'General Payment' }}</strong></div><div><span>Method</span><strong>{{ ucfirst(str_replace('_',' ',$payment->payment_method)) }}</strong></div></div><div class="sms-receipt-total"><span>Amount Paid</span><strong>₹{{ number_format($payment->amount,2) }}</strong></div><p class="sms-print-note">Transaction ID: {{ $payment->transaction_id ?: 'N/A' }} · {{ $payment->remarks ?: 'No remarks' }}</p></div><div class="sms-print-actions"><button onclick="window.print()">Print / Save PDF</button></div></body></html>
